package com.medisphere.milestone3.exception;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(NoSuchElementException.class)@ResponseStatus(HttpStatus.NOT_FOUND)public Map<String,Object> notFound(NoSuchElementException e){return Map.of("status",404,"message",e.getMessage());}@ExceptionHandler(IllegalArgumentException.class)@ResponseStatus(HttpStatus.BAD_REQUEST)public Map<String,Object> bad(IllegalArgumentException e){return Map.of("status",400,"message",e.getMessage());}@ExceptionHandler(IllegalStateException.class)@ResponseStatus(HttpStatus.SERVICE_UNAVAILABLE)public Map<String,Object> unavailable(IllegalStateException e){return Map.of("status",503,"message",e.getMessage());}@ExceptionHandler(Exception.class)@ResponseStatus(HttpStatus.BAD_REQUEST)public Map<String,Object> other(Exception e){return Map.of("status",400,"message",e.getMessage()==null?"Request failed":e.getMessage());}}
